import re
import xml.etree.ElementTree as ET

def parse(f):
    s=open(f).read()
    # remove xml declaration? ET can parse
    ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    root=ET.fromstring(s)
    rows={}
    for row in root.findall('.//m:sheetData/m:row', ns):
        r=row.get('r')
        cells={}
        for c in row.findall('m:c', ns):
            cells[c.get('r')]={
                's':c.get('s'),
                't':c.get('t'),
                'v':(c.find('m:v',ns).text if c.find('m:v',ns) is not None else None),
                'f':(c.find('m:f',ns).text if c.find('m:f',ns) is not None else None),
                'is':(c.find('m:is/m:t',ns).text if c.find('m:is/m:t',ns) is not None else None),
            }
        rows[r]=cells
    return rows

o=parse('orig_input/xl/worksheets/sheet1.xml')
n=parse('out/xl/worksheets/sheet1.xml')

diff=[]
for r in sorted(set(o)|set(n)):
    oc=o.get(r,{}); nc=n.get(r,{})
    for coord in sorted(set(oc)|set(nc)):
        a=oc.get(coord,{}); b=nc.get(coord,{})
        # compare style and type ignoring value
        if a.get('s')!=b.get('s') or a.get('t')!=b.get('t') or a.get('f')!=b.get('f'):
            diff.append((coord, a, b))
print('style/type/formula diffs:', len(diff))
for d in diff[:50]:
    print(d)
