import openpyxl
from openpyxl.utils import get_column_letter

gold='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_42058_answer_template_9021_golden.xlsx'
out='/tmp/llm_rollout_byuu9__b/3_42058_answer_template_9021_input.xlsx'

def extract(f):
    wb=openpyxl.load_workbook(f, data_only=False)
    ws=wb['Tabelle1']
    data={}
    formulas={}
    for r in range(8,19):
        for c in range(2,18):
            cell=ws.cell(row=r,column=c)
            coord=cell.coordinate
            v=cell.value
            if v is None: continue
            if isinstance(v,str) and v.startswith('='):
                formulas[coord]=v
            else:
                data[coord]=v
    return data, formulas

g_data, g_form = extract(gold)
o_data, o_form = extract(out)

print('gold data', len(g_data), 'formulas', len(g_form))
print('out  data', len(o_data), 'formulas', len(o_form))
print('data keys equal:', set(g_data)==set(o_data))
print('data values equal:', g_data==o_data)
print('formula keys equal:', set(g_form)==set(o_form))
print('formula values equal:', g_form==o_form)

# print missing/mismatches
if g_data!=o_data:
    for k in g_data:
        if o_data.get(k)!=g_data[k]:
            print('DATA MISMATCH', k, 'gold', g_data[k], 'out', o_data.get(k))
if g_form!=o_form:
    for k in g_form:
        if o_form.get(k)!=g_form[k]:
            print('FORMULA MISMATCH', k, 'gold', g_form[k], 'out', o_form.get(k))

